  ('9f22294e-16ab-d5c1-2479-56309d6da718', '/images/himalaya/valley-of-flowers.jpg', 'A green U-shaped valley opening towards snow peaks in Valley of Flowers National Park', 'Valley of Flowers National Park, Chamoli', 2400, 1600, 'data:image/jpeg;base64,', 'Rohit Sharma', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:Valley_of_flowers_national_park,_Uttarakhand,_India_01.jpg'),
  ('8064333d-dc61-2e35-2d5a-f02696d7ba2e', '/images/himalaya/deoria.jpg', 'A small green lake in a dry autumn meadow with snow peaks behind, at Deoria Tal', 'Deoria Tal, Rudraprayag', 2400, 1600, 'data:image/jpeg;base64,', 'Rajborah123', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:Deoria_tal.jpg'),
