insert into public.home_sections (id, type, position, enabled, eyebrow, title, accent, body, cta_label, cta_url, cta2_label, cta2_url, media_id, data) values
  ('00243333-0826-65db-67e0-64b4f12091a2', 'hero', 0, true, 'Uttarakhand · Garhwal & Kumaon', 'Find the villages', 'the map forgot.', 'Stay with mountain families, walk ancient trails, eat from Garhwali and Kumaoni kitchens, and wake to a view that resets you.', 'Explore villages', '/villages', 'Plan my trip', '/trip-planner', '39a62313-f0c8-f0e5-d21d-65120fb7cb0b', '{}'::jsonb),
  ('f2003ed7-2a3a-543c-20f8-be4ee0763f05', 'intro', 10, true, 'The Himalayan Roots', 'We take you to the hamlets where the road ends and the hospitality begins:', 'slate roofs, woodsmoke, and a kitchen that feeds you like family.', '', '', '', '', '', null, '{"items":[{"icon":"flame","title":"Hosted by families","text":"You stay in homes, not hotels, and eat what the household eats."},{"icon":"footprints","title":"Slow by design","text":"Fewer places, longer stays. Walk the lanes, join the fields, learn the trail names."},{"icon":"mountain","title":"Rooted in place","text":"Routes shaped around the village, the season and the weather, not a checklist."}]}'::jsonb),
  ('bfa9f75b-18ab-55bd-78d1-269d0c7c9e7b', 'regions', 20, true, 'Two cultures, one range', 'Garhwal and Kumaon', '', '', '', '', '', '', null, '{"items":[{"title":"Garhwal","subtitle":"Where the peaks have names and the temples are older.","text":"Chaukhamba, Kedar and the Mandakini valley. Stone-and-slate villages, jhangora millet and festivals that still gather the whole valley.","mediaId":"a02a00c7-7e2b-a0ec-365d-59fba241645b","url":"/villages"},{"title":"Kumaon","subtitle":"Oak forests, carved doors and the Panchachuli skyline.","text":"Aipan art on the floors, bhatt ki churkani on the stove and ridge after ridge of blue forest running to Nanda Devi.","mediaId":"a34eb903-58d7-3929-22d4-406dc1200c5b","url":"/villages"}]}'::jsonb),
  ('5e75fd60-ab4e-9c06-8697-ca920f10b25e', 'destinations', 30, true, 'Handpicked', 'Villages worth', 'the detour', '', 'All villages', '/villages', '', '', null, '{"kind":"villages","limit":5}'::jsonb),
  ('36a7e9f3-8f5c-9c2c-d5d9-2ead7e46b479', 'ad', 40, true, '', '', '', '', '', '', '', '', null, '{"placement":"home_middle"}'::jsonb),
  ('66417602-bc42-b76f-0b6e-da11eeb24b87', 'banner', 50, true, '', 'In the hills, the mist is', 'part of the itinerary.', 'Every season gives you a different mountain: snow in winter, rhododendron in spring, cloud and waterfalls in the monsoon, glass-clear peaks in autumn.', '', '', '', '', '09dcff7f-430a-c95f-3495-aafc5d79ce08', '{}'::jsonb),
  ('d48b4111-a7bf-2cb5-aeb5-4dc37e9f438b', 'split', 60, true, 'Stay', 'Sleep inside', 'the architecture.', 'Carved deodar balconies, dry-stone terraces, slate roofs that shrug off the monsoon. A pahadi house is built around its courtyard and its kitchen, and so is a stay in one.', 'Browse homestays', '/homestays', '', '', null, '{"mediaIds":["a8f7129b-d58c-ccc5-2f52-ce573e15e7b1","9fbe5164-7f41-79f3-68b2-bdb7336be3e9","89dc6557-b5ed-4edb-c39c-e278d21c692a"],"items":[{"title":"Wood-fired meals cooked by your hosts"},{"title":"A hosted walk through the village and its fields"},{"title":"Small houses, a handful of guests at a time"}]}'::jsonb),
  ('b6cbf64d-4f0f-b7ec-b428-1e32e253dcdc', 'listings', 70, true, 'Walk', 'Trails that start at', 'a doorstep', '', 'All treks', '/trekking', '', '', null, '{"kind":"trekking","limit":3}'::jsonb),
  ('463f4b0a-04fe-c646-d299-01114e448852', 'mosaic', 80, true, 'Taste & craft', 'Learn it from', 'the hands that keep it.', 'Cook jhangora kheer on a clay chulha. Paint Aipan with rice paste. Sit in on a folk-music evening. Every experience is hosted by a family or artisan from the village itself.', 'See experiences', '/experiences', '', '', null, '{"mediaIds":["7b2a6f95-63bd-e724-fcfa-c1dad2cba4e4","0b588ab3-835e-84b2-a476-613969dc6187","ac9d6fb0-f69b-96db-9498-4e198ecc6377"]}'::jsonb),
  ('94bd92ac-a230-f0ff-f80b-d4bfdcf9e039', 'reviews', 90, true, 'Travellers', 'Words from', 'the trail', '', '', '', '', '', null, '{"limit":6}'::jsonb),
  ('640c8dc5-b455-8269-d7c5-5e5f03509bfb', 'cta', 100, true, 'Begin', 'Tell us the time you have.', 'We''ll shape the route.', 'A long weekend or a month. Walking, staying or working remotely with a proper desk and a view.', 'Open the trip planner', '/trip-planner', 'Explore workations', '/workation', 'fa9b48e7-603c-dcb3-88bd-2e58ba636b61', '{}'::jsonb)
